[172] = { en = "Children's Week", tier = 4,
  t = "Children's Week",
  d = "Wil je ons hier in het weeshuis helpen? Zegen je, vriend; je hulp tijdens Children's Week is van onschatbare waarde.$B$BNeem dit fluitje. Je kunt het maar korte tijd gebruiken - meestal niet langer dan Children's Week zelf. Als je het gebruikt, kun je praten met het kind waarvoor je beloofd hebt te zorgen. Als je het nog een keer gebruikt, stuur je het kind weg.$B$BGebruik het fluitje vooral, $N, en ontmoet je beschermeling! Het kind wil je vast heel graag ontmoeten.",
  o = "Gebruik de Orcish Orphan Whistle om te praten met het kind waarvoor je tijdens Children's Week zorgt.",
  c = "Zug zug! Ik heet Grunth, en jij zorgt dus voor mij? Je bent een avonturier, zoals mijn mama en papa waren. Mijn verzorgster zegt dat ze met eer zijn gestorven in de strijd. Ik ben blij je te ontmoeten.$B$BIk hoop dat we veel dingen samen gaan doen. Er zijn dingen die ik graag wil doen, en de verzorgster zegt dat je deze week een soort grote $gbroer:zus; voor me bent. Dat zou ik superleuk vinden.",
  g = { {"weeshuis", "orphanage"}, {"Zegen je", "bless you (zegenen)"}, {"onschatbare waarde", "invaluable worth (onschatbaar)"}, {"fluitje", "(little) whistle"}, {"meestal", "usually, typically"}, {"beloofd", "promised (beloven)"}, {"stuur je het kind weg", "you dismiss the child (wegsturen)"}, {"vooral", "by all means, especially"}, {"beschermeling", "ward, protégé"}, {"verzorgster", "carer, matron"}, {"eer", "honor"}, {"superleuk", "really great, so much fun"} },
},

[910] = { en = "Down at the Docks", tier = 4,
  t = "Naar de haven",
  d = "Ik heb verhalen gehoord over de machtige schepen die tussen Ratchet en Booty Bay varen! Het zou zo gaaf zijn om op de oceaan te varen en in veel grote zeeslagen te vechten. Misschien word ik later een machtige zeeman van de Horde! Jaaa!$B$BWil je me alsjeblieft meenemen naar de haven van Ratchet? Ik beloof dat ik niet het water in ga en geen problemen maak - ik wil alleen de grote boten zien en het zoute zeewater ruiken! Jaaa!",
  o = "Breng je beschermeling naar de haven van Ratchet in the Barrens.",
  p = "Zijn we er al?",
  c = "Wauw, de oceaan is ENORM! Er waren ook heel veel meeuwen en zo - het is net zo lawaaiig en druk als ik dacht. Er zijn ook piraten in de buurt - zo gaaf!$B$BBedankt dat je me naar Ratchet hebt gebracht, $N. Dat was echt geweldig!",
  e = "Ga naar de haven van Ratchet in the Barrens.",
  g = { {"haven", "harbor, docks"}, {"gaaf", "cool, awesome"}, {"zeeslagen", "sea battles (zeeslag)"}, {"zeeman", "sailor"}, {"zoute", "salty (zout)"}, {"ruiken", "smell"}, {"beschermeling", "ward, protégé"}, {"meeuwen", "seagulls (meeuw)"}, {"lawaaiig", "noisy"}, {"druk", "busy, bustling"} },
},

[911] = { en = "Gateway to the Frontier", tier = 4,
  t = "Poort naar de grens",
  d = "Ze zeggen dat Ashenvale de nieuwe grens is, en dat de Mor'shan Rampart in the Barrens de poort ernaartoe is. Het zou zo gaaf zijn om een pionier te zijn en alles wat je nodig hebt uit de ongetemde wildernis te halen! Ze zeggen dat de Horde en de Alliance daar in de toekomst het vaakst zullen botsen, en daar wil ik bij zijn, $N!$B$BWil je me alsjeblieft naar de Mor'shan Rampart brengen, zodat ik kan zien hoe de grens eruitziet? Ik wil zien waar de Horde die stinkende nachtelfen wegjaagt!",
  o = "Breng je beschermeling naar de Mor'shan Rampart in het noorden van the Barrens, vlak voordat je Ashenvale binnengaat.",
  p = "Zijn we er al?",
  c = "Wauw, in Ashenvale beleef je echte avonturen! Heb jij ooit in Ashenvale gevochten, $N? Als ik later een held word, wil ik naar Ashenvale komen en vechten voor de glorie van de Horde!$B$BBedankt dat je me naar de grens hebt gebracht, $N. Je bent de beste!",
  e = "Ga naar de Mor'shan Rampart in the Barrens.",
  g = { {"grens", "frontier, border"}, {"poort", "gateway, gate"}, {"ernaartoe", "to it, towards it"}, {"pionier", "pioneer"}, {"ongetemde", "untamed (ongetemd)"}, {"wildernis", "wilderness, wilds"}, {"botsen", "clash"}, {"stinkende", "smelly (stinkend)"}, {"wegjaagt", "drives out (wegjagen)"}, {"binnengaat", "enter (binnengaan)"}, {"beleef", "experience (beleven)"}, {"glorie", "glory"} },
},

[915] = { en = "You Scream, I Scream...", tier = 4,
  t = "Ik schreeuw, jij schreeuwt...",
  d = "IJSJE! O alsjeblieft alsjeblieft alsjeblieft, kun je wat ijs voor me halen?! Aardbei is mijn lievelingssmaak, en er is geen beter aardbeienijs op de wereld dan Tigule and Foror's Strawberry Ice Cream! Het is mijn lievelingsijs van de hele wereld!$B$BIk heb het lang geleden één keer gehad, toen ik bij de racebaan van de Shimmering Flats was, maar ik hoorde dat ze het nu misschien in de stad verkopen! Alsjeblieft? Alsjeblieft, alsjeblieft? Met Tigule and Foror's Strawberry Ice Cream erop??!?!",
  o = "Haal wat Strawberry Ice Cream voor je beschermeling. De jongen lijkt het ijs van het merk Tigule and Foror het liefst te hebben.",
  p = "Ik zou willen dat ze meer smaken ijs maakten dan alleen aardbei, maar ik heb maar geluk dat aardbei mijn lievelingssmaak is!",
  c = "Mmmmmmmmm! Ik ben dol op hun aardbeienijs! Als Tigule en Foror één ding kunnen, dan is het ijs maken!$B$BHeel erg bedankt, $N - dit is de lekkerste traktatie ooit!",
  g = { {"schreeuw", "scream (schreeuwen)"}, {"ijsje", "ice cream (cone)"}, {"aardbei", "strawberry"}, {"lievelingssmaak", "favorite flavor"}, {"aardbeienijs", "strawberry ice cream"}, {"racebaan", "race track"}, {"merk", "brand"}, {"het liefst", "most of all, prefer (liefst)"}, {"smaken", "flavors (smaak)"}, {"geluk", "luck"}, {"dol op", "crazy about, love (dol zijn op)"}, {"traktatie", "treat"} },
},

[925] = { en = "Cairne's Hoofprint", tier = 4,
  t = "De hoefafdruk van Cairne",
  d = "Ze zeggen dat Cairne Bloodhoof een van de grootste helden is die de Horde ooit heeft gehad. Als ik groot ben, wil ik ook een held van de Horde worden!$B$BKen jij Cairne, $N? Wil je iets voor me doen, alsjeblieft? Kun je zijn hoefafdruk voor me halen? Ik weet niet hoe ik het hem moet vragen, en hij heeft waarschijnlijk geen tijd voor iemand zoals ik... maar jij! Jij bent een avonturier, net als hij! Ik wed dat hij jou zomaar zijn hoefafdruk geeft!$B$BAlsjeblieft?",
  o = "Reis naar Thunder Bluff en probeer de hoefafdruk van Cairne Bloodhoof voor je beschermeling te krijgen.",
  p = "Toen de orcs alleen waren en geen vrienden hadden, verwelkomden de tauren hen in een vreemd land. Ze deelden met hen zonder er iets voor terug te vragen. Dat is eer, $N.",
  c = "WAUW! Je hebt Cairnes hoefafdruk voor me gehaald! Heel erg bedankt! En wauw... hij heeft er een persoonlijk berichtje op geschreven - voor mij! Ik wist wel dat hij echt cool zou zijn, ik wist het gewoon! Misschien bedank ik hem ooit zelf... als ik een held van de Horde word!$B$BJe bent de beste, $N. Bedankt dat je zo lief voor me bent.",
  g = { {"hoefafdruk", "hoofprint"}, {"waarschijnlijk", "probably"}, {"wed", "bet (wedden)"}, {"zomaar", "just like that, easily"}, {"verwelkomden", "welcomed (verwelkomen)"}, {"vreemd", "strange, foreign"}, {"deelden", "shared (delen)"}, {"terug te vragen", "to ask in return (terugvragen)"}, {"persoonlijk", "personal"}, {"berichtje", "little message (bericht)"}, {"ooit", "someday, ever"} },
},

[1800] = { en = "Lordaeron Throne Room", tier = 4,
  t = "De troonzaal van Lordaeron",
  d = "De verzorgsters in mijn tehuis vertellen 's avonds machtige verhalen over gevechten en oude geschiedenis als we braaf zijn en onze klusjes doen. Eén verhaal ging over hoe Lordaeron viel, en hoe de slechte Arthas zijn eigen vader doodde om koning te worden.$B$BHij had geen eer, $N! Als ik groot ben en een machtige krijger van de Horde word, laat mijn zwaard zich leiden door eer - nooit door het kwaad!$B$BWil je me alsjeblieft meenemen naar de troonzaal? Die ligt vlak voor de plek waar je naar beneden gaat, de Undercity in.",
  o = "Breng je beschermeling naar de oude Lordaeron Throne Room, die vlak voor de afdaling naar de Undercity ligt.$b",
  p = "Zijn we er al?",
  c = "Wat een enge troonzaal, $N! Hij stond leeg, maar het voelde alsof daar een groot kwaad is gebeurd. Ik voelde me boos... maar ik voelde me ook verdrietig. Ik begrijp waarom de verzorgsters ons zulke verhalen vertellen; ik zal mijn volk nooit zo verraden!$B$BBedankt dat je me naar de troonzaal hebt gebracht, $N. Ik heb veel geleerd.",
  e = "Ga naar de oude Lordaeron Throne Room, die vlak voor de afdaling naar de Undercity ligt.",
  g = { {"troonzaal", "throne room"}, {"verzorgsters", "carers, matrons (verzorgster)"}, {"tehuis", "home (institution)"}, {"braaf", "good, well-behaved"}, {"klusjes", "chores (klusje)"}, {"zich leiden", "be guided (leiden)"}, {"het kwaad", "evil"}, {"afdaling", "descent"}, {"eng", "scary"}, {"verdrietig", "sad"}, {"verraden", "betray"} },
},

[5502] = { en = "A Warden of the Horde", tier = 4,
  t = "Een beschermer van de Horde",
  d = "Je bent zo ontzettend lief voor me geweest, $N. Ik had nooit gedacht dat ik zoveel plezier zou hebben tijdens Children's Week. Dank je. Ik ga niet verdrietig zijn over wat er met me is gebeurd - mijn ouders zeiden altijd dat ik boven alle slechte dingen moest uitstijgen die gebeuren. Ik word een held... net als jij.$B$BHet spijt me het te zeggen, maar het is tijd om naar huis te gaan. Laten we teruggaan, dan vertel ik de verzorgster wat een geweldig iemand je bent!",
  o = "Breng je beschermeling terug naar het weeshuis van Orgrimmar door de Orcish Orphan Whistle in te leveren bij Orphan Matron Battlewail in the Valley of Honor.",
  p = "Fijn je weer te zien, $N. Heb je de taken gedaan die je vrijwillig op je hebt genomen tijdens Children's Week?",
  c = "Mogen de geesten je zegenen, $N. Je hebt meer voor Grunth gedaan dan de meesten ooit zouden bedenken om voor hem te doen. Dank je - jij bent het toonbeeld van wat het betekent om een held van de Horde te zijn.$B$BAlsjeblieft - kom ons nog eens bezoeken als je tijd hebt. Ik weet dat Grunth dat leuk zou vinden, en ik ook.$B$BGrunth heeft zoveel plezier met je gehad, $N. Hij wilde je een van zijn lievelingsdieren geven, zodat je aan hem blijft denken.",
  g = { {"beschermer", "warden, protector"}, {"ontzettend", "extremely, so very"}, {"uitstijgen", "rise above (uitstijgen boven)"}, {"Het spijt me", "I'm sorry (spijten)"}, {"in te leveren", "to hand in (inleveren)"}, {"vrijwillig", "voluntarily"}, {"op je hebt genomen", "have taken on (op zich nemen)"}, {"zegenen", "bless"}, {"bedenken", "think of, come up with"}, {"toonbeeld", "epitome, model"}, {"lievelingsdieren", "favorite pets (lievelingsdier)"} },
},

[6163] = { en = "Ramstein", tier = 4,
  t = "Ramstein",
  d = "Ik werd overweldigd. Precies op deze hoeve stond ik... ik hield stand om Lordaeron te verdedigen. De boerderij en alles erop werd overvallen door een gigantische golf van de Scourge.$B$BHet ellendige wezen. Het vuil. Het zweefde boven me, met ingewanden die uit zijn wijd open borstholte hingen.$B$BIk werd wakker als Scourge. Zo lang was ik hulpeloos. Mijn geest was samengesmolten met die van de Lich King.$B$BZij kwam me halen... ergens, op de een of andere manier, wist ik dat ze zou komen. Vrij.$B$BEn nu moet ik mijn wraak hebben - wraak op dat wat mijn leven van me afnam. Vernietig het.",
  o = "Reis naar Stratholme en dood Ramstein the Gorger. Neem zijn hoofd mee als aandenken voor Nathanos.",
  p = "Nadat Sylvanas me had bevrijd, joeg ik maandenlang op het beest door deze woeste landen. Het vluchtte naar de veiligheid van Stratholme. De smeerlap...",
  c = "Ik vraag me af... heeft het om genade gesmeekt? Zou het weten wat genade is?$B$B<Nathanos spuugt.>$B$BIk hang de kop van dit beest aan mijn muur.$B$BJe hebt een plek verdiend onder mijn kampioenen, $N.$B$B<Nathanos salueert.>",
  g = { {"overweldigd", "overwhelmed (overweldigen)"}, {"hoeve", "farmstead"}, {"hield stand", "held my ground (standhouden)"}, {"overvallen", "overrun, attacked by surprise (overvallen)"}, {"ellendige", "wretched (ellendig)"}, {"zweefde", "hovered (zweven)"}, {"ingewanden", "entrails, guts"}, {"borstholte", "chest cavity"}, {"hulpeloos", "helpless"}, {"samengesmolten", "merged, fused (samensmelten)"}, {"wraak", "vengeance, revenge"}, {"aandenken", "souvenir, keepsake"}, {"woeste", "wild, desolate (woest)"}, {"smeerlap", "bastard, scumbag"}, {"gesmeekt", "begged (smeken)"}, {"salueert", "salutes (salueren)"} },
},

[8387] = { en = "Invaders of Alterac Valley", tier = 4,
  t = "Indringers van Alterac Valley",
  d = "De strijd om Alterac woedt door! Je moet teruggaan naar Alterac Valley en de indringers nog een keer uit het gebied van de Frostwolf verdrijven, $N!",
  o = "Breng 3 Alterac Valley Marks of Honor naar een Horde Warbringer buiten de slagvelden.",
  p = "De strijd om Alterac woedt door! Je moet teruggaan naar Alterac Valley en de indringers nog een keer uit het gebied van de Frostwolf verdrijven, $N!",
  c = "Goed werk, $N! Je mag trots op jezelf zijn. De indringers van de Alliance moeten uit Alterac worden verdreven!",
  g = { {"indringers", "invaders (indringer)"}, {"woedt door", "rages on (doorwoeden)"}, {"gebied", "territory, area"}, {"verdrijven", "drive out, expel"}, {"slagvelden", "battlegrounds (slagveld)"}, {"trots", "proud"}, {"verdreven", "expelled, driven out (verdrijven)"} },
