[8481] = { en = "The Root of All Evil", tier = 4,
  t = "De wortel van alle kwaad",
  d = "$N, dankzij jou hebben we een manier bedacht om de wortel van alle kwaad voor de Winterfall-stam op te roepen: de demon die hen verdorven maakt en over hen heerst!$B$BBreng deze fakkel naar de ingang van de persoonlijke grot van High Chief Winterfall en zet hem daar in de grond. Daardoor wordt de demon gedwongen zich te laten zien en te komen kijken. Op dat moment moeten jij en je bondgenoten hem neerslaan! Alleen de essentie van de verslagen demon kan het lange genezingsproces van de Winterfall-stam beginnen... en de redding van Timbermaw Hold.",
  o = "Zet de Demon Summoning Torch neer in de ingang van de grot van High Chief Winterfall in het furbolgdorp van de Winterfall. Versla de demon en haal de Essence of Xandivious op voor Gorn One Eye in Timbermaw Hold.",
  p = "Je bent bij ons teruggekomen, $N... betekent dit dat de demon is gedood?",
  c = "Je... je hebt ons gered! Doordat je de demon Xandivious hebt verslagen, is Timbermaw Hold nog jaren veilig. Je bent echt een held onder ons soort.$B$BNeem dit alsjeblieft aan, met onze zegen. Het genezingsproces bij de furbolgs zal langzaam gaan - en het conflict gaat nog door - maar je hebt de Winterfall iets gegeven wat ze voor vandaag nooit hadden.$B$BZe hebben een kans om te overleven.",
  g = { {"wortel", "root"}, {"bedacht", "devised, thought up (bedenken)"}, {"op te roepen", "to summon (oproepen)"}, {"verdorven", "corrupt, depraved"}, {"heerst", "rules, dominates (heersen)"}, {"fakkel", "torch"}, {"gedwongen", "forced (dwingen)"}, {"bondgenoten", "allies (bondgenoot)"}, {"neerslaan", "strike down"}, {"essentie", "essence"}, {"genezingsproces", "healing process"}, {"redding", "salvation, rescue"}, {"zegen", "blessing"}, {"overleven", "survive"} },
},

[8485] = { en = "The Brokering of Peace", tier = 4,
  t = "Vrede tot stand brengen",
  d = "Je daden gaan verder dan het verhaal van een eenvoudige held, $N. Als jij een vertegenwoordiger van je volk bent, dan is je volk een volk waarmee we vrede willen sluiten.$B$BBreng dit geschenk alsjeblieft naar de warchief van de orcs, die in het land Durotar woont; ik geloof dat jullie deze stad Orgrimmar noemen. Vroeger heeft hij geprobeerd namens zijn Horde contact met ons te zoeken. Het is nu alleen maar passend om jou te erkennen als de sleutel in de pogingen van je Horde om vrede tot stand te brengen.",
  o = "Breng de Timbermaw Offering of Peace naar Thrall in Orgrimmar.",
  p = "De warchief begroet je, $C. Je daden maken de Horde sterker in deze moeilijke tijden. Welnu, wat kom je bij me doen?",
  c = "Dit is inderdaad een zeer gelukkige wending. Als er een blijvende vrede met deze wezens zou komen, zou dat ons zeker een voordeel geven bij het beschermen van Kalimdor tegen dreigingen van buitenaf. Ik zal de andere leiders van de Horde hier meteen van op de hoogte brengen, en er zullen meer diplomaten worden gestuurd!$B$BEn jij, $N... je hebt moed getoond, zowel in diplomatie als in actie. Ik dank je, net als de hele Horde.",
  g = { {"tot stand brengen", "bring about, broker"}, {"daden", "deeds (daad)"}, {"vertegenwoordiger", "representative"}, {"vrede sluiten", "make peace"}, {"geschenk", "gift, offering"}, {"namens", "on behalf of"}, {"passend", "fitting, appropriate"}, {"erkennen", "acknowledge, recognize"}, {"pogingen", "efforts, attempts (poging)"}, {"begroet", "greets (begroeten)"}, {"wending", "turn (of events)"}, {"blijvende", "lasting (blijvend)"}, {"dreigingen", "threats (dreiging)"}, {"op de hoogte brengen", "inform, notify"}, {"moed", "courage"} },
},

[8787] = { en = "Armor Kits for the Field", tier = 4,
  t = "Pantserkits voor het veld",
  d = "De dappere vrijwilligers van het Orgrimmar Legion zijn in Silithus aangekomen om ons te helpen in onze strijd. Hun voorraad pantserkits is tijdens de reis op de een of andere manier verloren gegaan. Haal een partij pantserkits en lever ze af bij Merok Longstride, bij het kamp van het Orgrimmar Legion.",
  o = "Breng 8 Rugged Armor Kits en 8 Heavy Armor Kits naar Merok Longstride bij Hive'Regal. Je moet ook Logistics Task Briefing VII meebrengen om deze quest te voltooien.",
  p = "Heb je iets voor me, $N?",
  c = "Ah, ja... Ik zal deze onder de troepen verdelen, $N. Het Orgrimmar Legion dankt je!",
  g = { {"vrijwilligers", "volunteers (vrijwilliger)"}, {"voorraad", "supply, stock"}, {"pantserkits", "armor kits (pantserkit)"}, {"op de een of andere manier", "somehow"}, {"verloren gegaan", "got lost (verloren gaan)"}, {"partij", "batch, lot"}, {"lever ze af", "deliver them (afleveren)"}, {"voltooien", "complete, finish"}, {"verdelen", "distribute, divide"}, {"troepen", "troops (troep)"} },
},

[9416] = { en = "Report to General Kirika", tier = 4,
  t = "Meld je bij General Kirika",
  d = "Jij bent vast een van de nieuwe rekruten van General Kirika. Werd tijd dat je kwam. Lichamen slijten snel in de woestijn.$b$bDe dwergen krijgen elke dag versterking, en we kunnen het ons niet veroorloven terrein te verliezen in onze strijd om grondstoffen in Silithus.$b$bHaal je instructies bij de General. Het is niet mijn taak om je te trainen, alleen om je te vinden.",
  o = "Spreek met General Kirika in het kamp van de Horde bij Hive'Regal.",
  c = "Goed dat je er bent, maar we hebben geen tijd om te verspillen aan kletspraatjes. Je hebt instructies nodig, en dan moet je erop uit.$b$bLuister goed.",
  g = { {"Meld je", "report (zich melden)"}, {"rekruten", "recruits (rekruut)"}, {"Werd tijd", "about time (het werd tijd)"}, {"slijten", "wear down, wear out"}, {"versterking", "reinforcements"}, {"veroorloven", "afford (zich veroorloven)"}, {"terrein", "ground, terrain"}, {"grondstoffen", "resources, raw materials (grondstof)"}, {"verspillen", "waste"}, {"kletspraatjes", "small talk, chit-chat (kletspraatje)"}, {"erop uit", "out there, out into the field (erop uit gaan)"} },
},

[9422] = { en = "Scouring the Desert", tier = 4,
  t = "De woestijn doorzoeken",
  d = "Al een tijd halen we kristallen uit de woestijn van Silithus. De enige gevaren kwamen van de wezens die hier wonen, en van het zand, het stof en de drukkende hitte.$b$bMaar nu lijkt de Alliance door te hebben wat we hier hebben gevonden. Het is nu een race tussen ons om de natuurlijke grondstoffen te veroveren en ze bij de ander weg te houden.$b$bIk heb elk paar handen nodig dat beschikbaar is. Ik hoop dat ik de jouwe heb.",
  o = "Vind Silithyst en lever het af bij de Silithyst Extractor. Spreek daarna met General Kirika in het kamp van de Horde bij Hive'Regal.",
  p = "Pas op voor de gevaren van de woestijn, $n. Nu de Alliance tussen de duinen op de loer ligt, kan elke stap je laatste zijn.",
  c = "Goed gedaan, $n. Deze grondstoffen gaan naar onze voorraden, en elk beetje is winst voor ons en verlies voor onze vijand.$b$b",
  o1 = "Lever Silithyst af",
  g = { {"doorzoeken", "search, scour"}, {"drukkende", "oppressive, stifling (drukkend)"}, {"hitte", "heat"}, {"door te hebben", "to have caught on (doorhebben)"}, {"veroveren", "capture, conquer"}, {"weg te houden", "keep away (weghouden)"}, {"beschikbaar", "available"}, {"duinen", "dunes (duin)"}, {"op de loer ligt", "lurks (op de loer liggen)"}, {"voorraden", "stockpiles, supplies (voorraad)"}, {"winst", "gain, profit"}, {"verlies", "loss"} },
},

[8053] = { en = "Paragons of Power: The Freethinker's Armguards", tier = 4,
  t = "Paragons of Power: De armbeschermers van de vrijdenker",
  d = "Jij bent een heiden. Heidenen hebben een plaats in de stam. Heidenen zijn de vrijdenkers van Zandalar. Vrijdenkers zijn niet bang voor onderdrukking. Vrijdenkers sterven voor waar ze in geloven. Wij weten dat jij zou sterven voor waar jij in gelooft. Dat verdient onze erkenning. Dat geeft je een kans om jezelf verder te bewijzen.$B$BWe moeten de Paragons of Power hebben. Ga naar Zul'Gurub. Dood de dienaren van Hakkar. Kom terug als je hebt wat ik zoek. Eis de eerste strijduitrusting van een vrijdenker van Zandalar op.$B$BGa.",
  o = "Breng Primal Hakkari Bindings naar Jin'rokh the Breaker. Je moet ook een reputatie van Friendly of hoger hebben bij de Zandalar Tribe.$B$BJin'rokh the Breaker is te vinden op Yojamba Isle, Stranglethorn Vale.",
  p = "Ben je terug? Heb je de Paragons of Power? Verspil je mijn tijd?$B$BIk hoop het niet, heiden.",
  c = "Je eert ons zeer. Het bloed van de dienaren van Hakkar druipt van je handen. Je bent een vriend van de stam.$B$BDraag deze armbeschermers. Het zijn de armbeschermers van de vrijdenker. Dit bedoel ik met echte kracht.",
